  const gRandRange = G("randrange", (r) => { const a = int(r, 1, 5), b = a + int(r, 3, 9); return fact(r, "What are the smallest and largest values random.randint(" + a + ", " + b + ") can give?", a + " and " + b, [a + " and " + (b - 1), (a + 1) + " and " + b, "0 and " + b], "randint is INCLUSIVE: both " + a + " and " + b + " can come up."); });
  const gRandCount = G("randcount", (r) => { const a = int(r, 1, 5), b = a + int(r, 3, 9), c = b - a + 1; return fact(r, "How many different values can random.randint(" + a + ", " + b + ") give?", String(c), [String(c - 1), String(c + 1), String(b)], "Count both ends: " + b + " - " + a + " + 1 = " + c + "."); });
