  const gFnPrint = G("fnprint", (r) => { const n = pick(r, NAMES), v = r() < 0.5; return v ? run(r, "What does this program print?", "def greet(name):\n    print(\"Hello\", name)\ngreet(" + q1(n) + ")", "Hello " + n, ["Hello name", "greet " + n, "Nothing is printed"], "The argument " + q1(n) + " is copied into the parameter name, so print shows Hello " + n + ".") : run(r, "What does this program print?", "def shout(word):\n    print(word + \"!\")\nshout(" + q1(n) + ")", n + "!", ["word!", n, "shout " + n], "The argument goes into word, and print joins it with the exclamation mark."); });
  const gFnTwice = G("fntwice", (r) => { const a = pick(r, NAMES), b = pick(r, NAMES.filter((x) => x !== a)); return run(r, "What does this program print?", "def greet(name):\n    print(\"Hi\", name)\ngreet(" + q1(a) + ")\ngreet(" + q1(b) + ")", "Hi " + a + "\nHi " + b, [th(["Hi " + b, "Hi " + a]), th(["Hi " + a, "Hi " + a]), "Hi name then Hi name"], "Each call runs the function again with a different argument. The calls run in the order they are written."); });
  const gFnNoCall = G("fnnocall", (r) => { const f1 = pick(r, ["greet", "hello", "welcome", "salute"]), w = pick(r, ["Hello", "Hi", "Welcome", "Hey"]), end = pick(r, ["Done", "Finished", "End", "Bye"]); return run(r, "What does this program print?", "def " + f1 + "(name):\n    print(" + q1(w) + ", name)\nprint(" + q1(end) + ")", end, [w + " name then " + end, w + " " + pick(r, NAMES), "Nothing is printed"], "def only DEFINES the function. It does not run until it is CALLED, and nobody called " + f1 + ", so only " + end + " is printed."); });
  const gFnMath = G("fnmath", (r) => { const k = int(r, 2, 6), n = int(r, 2, 9); return run(r, "What does this program print?", "def times(n):\n    print(n * " + k + ")\ntimes(" + n + ")", String(n * k), [String(n + k), String(n), String(k)], "n is " + n + " inside the function, so it prints " + n + " * " + k + " = " + n * k + "."); });
